// Build the offers app's own signed bundle: a guest holding no module, only a keyspace
// and a name (browser/offers-app.js). Unlike a chat app's `.skb`
// (scripts/build-app-bundle.mjs), this one is not something a user drops in — it is
// loaded at BOOT, alongside the transport bundle, so its bytes have to reach the served
// page rather than sit in the gitignored bundle/ directory. This script therefore also
// generates browser/offers-bundle.js, a tracked module in the shape of seedkernel's
// host/transport-bundle.ts: the blob embedded as base64, so the page's own boot code can
// import it like any other browser/ file.
//
//   node scripts/build-offers-bundle.mjs
//
// Signed under chat-author.key — the SAME author every chat-app build signs under
// (scripts/build-app-bundle.mjs mints it on first run): an author is a key set, not a
// program, and this demo has exactly one. Its freshness lineage is its own, though:
// offers-author.version tracks this app's high-water mark separately from
// chat-author.version's, because the runtime's freshness store keys on (author, app)
// and "offers" is a different app than "chat".

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { loadCrypto } from "seedkernel-wasm";
import { authorBundle, hybridAuthorKeysFromSeed } from "seedkernel-wasm/bundle-author";
import { OFFER_PROTO, OFFERS_APP, OFFERS_REQUIRES, offersGuestSource } from "../browser/offers-app.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");

const toHex = (b) => Buffer.from(b).toString("hex");
const fromHex = (h) => Uint8Array.from(Buffer.from(h, "hex"));

const sodium = await loadCrypto();

// The author key: read, never minted, here — build-app-bundle.mjs owns minting it, since
// a clean clone builds a chat app before it ever needs an offers bundle (`npm run build`
// orders them that way in package.json).
const keyPath = join(root, "chat-author.key");
if (!existsSync(keyPath)) {
  throw new Error(`${keyPath} not found — run a chat-app build first `
    + "(npm run build:chat-app-v1 mints it via scripts/build-app-bundle.mjs)");
}
const sk = fromHex(readFileSync(keyPath, "utf8").trim());

// Freshness: this app's OWN high-water mark, beside the key but under its own file —
// chat-author.version belongs to the "chat" app; "offers" is a different (author, app)
// pair and keeps its own count, for the same reason build-app-bundle.mjs keeps one for
// "chat" rather than resetting to 1 on every run.
const versionPath = join(root, "offers-author.version");
let prevVersion = 0;
if (existsSync(versionPath)) {
  const v = Number(readFileSync(versionPath, "utf8").trim());
  if (Number.isInteger(v) && v > 0) prevVersion = v;
}
const version = prevVersion + 1;

const keys = hybridAuthorKeysFromSeed(sodium, sk.slice(0, 32));

const { blob, manifest, author } = authorBundle(sodium, keys, {
  app: OFFERS_APP,
  version,
  protocols: [OFFER_PROTO],
  // A guest-only bundle: no module, because this app is a keyspace and a claim and does
  // no transform of its own (browser/offers-app.js).
  modules: [],
  guestSource: offersGuestSource(),
  guestRequires: OFFERS_REQUIRES,
});

writeFileSync(versionPath, `${version}\n`);

const skbOutPath = join(root, "bundle", "offers.skb");
mkdirSync(dirname(skbOutPath), { recursive: true });
writeFileSync(skbOutPath, blob);

const b64 = Buffer.from(blob).toString("base64");
const js = `// GENERATED by scripts/build-offers-bundle.mjs — DO NOT EDIT.
// The offers app's own boot bundle (browser/offers-app.js) — a second boot bundle,
// loaded at boot exactly like the kernel's transport bundle, signed by
//   ${toHex(author)}
// under the hybrid suite 0x02 (Ed25519 + ML-DSA-65) with chat-author.key, the same
// author every chat-app bundle signs under. Its own freshness lineage lives in
// offers-author.version: the runtime's freshness store keys on (author, app), and
// "offers" is not "chat".
//
// The page is served from browser/ (bundle/ is not), so this embedded module is how the
// boot bundle reaches the tab — the shape of seedkernel's host/transport-bundle.ts.
const OFFERS_BUNDLE_B64 = "${b64}";
let decoded = null;
/** The offers app's boot bundle as raw bytes. A fresh copy per call; the blob is a value
 *  callers may hand to the bundle loader, which does not mutate it but is not relied on
 *  either. */
export function offersBundleBytes() {
  if (decoded === null) {
    const bin = atob(OFFERS_BUNDLE_B64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    decoded = out;
  }
  return decoded.slice();
}
/** The author this bundle is signed by (hex) — what \`admit\` pins the boot load to
 *  (chat-shell.js), read off the artifact rather than restated by hand. */
export const OFFERS_AUTHOR_HEX = "${toHex(author)}";
/** The app name this bundle's manifest declares (browser/offers-app.js \`OFFERS_APP\`) —
 *  what \`admit\` checks alongside the author. */
export const OFFERS_APP = ${JSON.stringify(manifest.app)};
`;
writeFileSync(join(root, "browser", "offers-bundle.js"), js);

console.log(`  author ${toHex(author)} (hybrid 0x02)`);
console.log(`  wrote bundle/offers.skb (app ${manifest.app} v${manifest.version})`);
console.log(`  wrote browser/offers-bundle.js`);
